def _assert_compiled_execution_preserves_outputs_gradients(
    _case_context,
    symbols,
    case,
):
    _lawspec_assert(
        _case_context + " — laws/conformance.lawspec:277",
        lambda: _definitions.equivalent(
            symbols,
            _lawspec_schema.from_native(
                _schema.Named("tensorloom_contracts.conformance::type::Observation"),
                impl.observe(
                    _lawspec_schema.to_native(
                        _schema.Named(
                            "tensorloom_contracts.conformance::type::ConformanceCase",
                        ),
                        _lawspec_schema.validate(
                            _schema.Named(
                                "tensorloom_contracts.conformance::type::ConformanceCase",
                            ),
                            case,
                            MACHINE_BITS,
                            symbols,
                        ),
                        MACHINE_BITS,
                        symbols,
                    ),
                ),
                MACHINE_BITS,
                symbols,
            ),
            _lawspec_schema.from_native(
                _schema.Named("tensorloom_contracts.conformance::type::Observation"),
                impl.reference(
                    _lawspec_schema.to_native(
                        _schema.Named(
                            "tensorloom_contracts.conformance::type::ConformanceCase",
                        ),
                        _lawspec_schema.validate(
                            _schema.Named(
                                "tensorloom_contracts.conformance::type::ConformanceCase",
                            ),
                            case,
                            MACHINE_BITS,
                            symbols,
                        ),
                        MACHINE_BITS,
                        symbols,
                    ),
                ),
                MACHINE_BITS,
                symbols,
            ),
        ),
        lambda: True,
        "Bool",
        "Bool",
    )


